-- Cards, financial-product marketplace, provider capabilities and webhook idempotency.
create table if not exists public.wallet_cards (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,wallet_id uuid not null references public.wallets(id) on delete cascade,card_type text not null check(card_type in ('virtual','physical')),provider text,provider_card_id text,status text not null default 'pending' check(status in ('pending','active','frozen','cancelled','expired')),last4 text,brand text,expiry_month integer,expiry_year integer,spending_limit numeric,currency text not null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.financial_products (id uuid primary key default gen_random_uuid(),provider text not null,product_type text not null check(product_type in ('insurance','loan','credit_line','savings','investment','invoice_finance','asset_finance','merchant_cash_advance')),name text not null,country_codes text[] not null default '{}',currency_codes text[] not null default '{}',description text,eligibility_rules jsonb not null default '{}'::jsonb,pricing_rules jsonb not null default '{}'::jsonb,application_url text,api_capabilities jsonb not null default '{}'::jsonb,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.financial_product_applications (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,product_id uuid not null references public.financial_products(id),status text not null default 'draft' check(status in ('draft','submitted','under_review','approved','declined','withdrawn','expired')),requested_amount numeric,currency text,purpose text,provider_reference text,decision_data jsonb not null default '{}'::jsonb,documents jsonb not null default '[]'::jsonb,created_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.business_policies (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,product_id uuid references public.financial_products(id),policy_type text not null,provider text,policy_number text,status text not null default 'active' check(status in ('quote','active','expired','cancelled','claimed')),coverage_amount numeric,premium_amount numeric,currency text,start_date date,end_date date,renewal_date date,claim_contact text,documents jsonb not null default '[]'::jsonb,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.wallet_provider_capabilities (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,provider text not null,integration_id uuid references public.integrations(id) on delete set null,capabilities jsonb not null default '{}'::jsonb,status text not null default 'unknown' check(status in ('unknown','connected','degraded','disabled')),last_verified_at timestamptz,last_error text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,provider));
create table if not exists public.wallet_webhook_events (id uuid primary key default gen_random_uuid(),business_id uuid references public.businesses(id) on delete cascade,provider text not null,external_event_id text not null,event_type text not null,payload jsonb not null,signature_verified boolean not null default false,processing_status text not null default 'received' check(processing_status in ('received','processing','processed','ignored','failed')),attempts integer not null default 0,error_message text,received_at timestamptz not null default now(),processed_at timestamptz,unique(provider,external_event_id));
create index if not exists wallet_cards_business_idx on public.wallet_cards(business_id,status);
create index if not exists financial_products_type_country_idx on public.financial_products(product_type,active);
create index if not exists financial_product_applications_business_idx on public.financial_product_applications(business_id,created_at desc);
create index if not exists business_policies_business_idx on public.business_policies(business_id,status);
create index if not exists wallet_provider_capabilities_business_idx on public.wallet_provider_capabilities(business_id,status);
create index if not exists wallet_webhook_events_business_idx on public.wallet_webhook_events(business_id,received_at desc);
alter table public.wallet_cards enable row level security; alter table public.financial_products enable row level security; alter table public.financial_product_applications enable row level security; alter table public.business_policies enable row level security; alter table public.wallet_provider_capabilities enable row level security; alter table public.wallet_webhook_events enable row level security;
grant select,insert,update,delete on public.wallet_cards,public.financial_products,public.financial_product_applications,public.business_policies,public.wallet_provider_capabilities,public.wallet_webhook_events to authenticated;
create policy wallet_cards_owner_all on public.wallet_cards for all to authenticated using(exists(select 1 from public.businesses b where b.id=wallet_cards.business_id and b.owner_id=(select auth.uid()))) with check(exists(select 1 from public.businesses b where b.id=wallet_cards.business_id and b.owner_id=(select auth.uid())));
create policy financial_products_read on public.financial_products for select to authenticated using(active=true);
create policy financial_product_applications_owner_all on public.financial_product_applications for all to authenticated using(exists(select 1 from public.businesses b where b.id=financial_product_applications.business_id and b.owner_id=(select auth.uid()))) with check(exists(select 1 from public.businesses b where b.id=financial_product_applications.business_id and b.owner_id=(select auth.uid())));
create policy business_policies_owner_all on public.business_policies for all to authenticated using(exists(select 1 from public.businesses b where b.id=business_policies.business_id and b.owner_id=(select auth.uid()))) with check(exists(select 1 from public.businesses b where b.id=business_policies.business_id and b.owner_id=(select auth.uid())));
create policy wallet_provider_capabilities_owner_all on public.wallet_provider_capabilities for all to authenticated using(exists(select 1 from public.businesses b where b.id=wallet_provider_capabilities.business_id and b.owner_id=(select auth.uid()))) with check(exists(select 1 from public.businesses b where b.id=wallet_provider_capabilities.business_id and b.owner_id=(select auth.uid())));
create policy wallet_webhook_events_owner_all on public.wallet_webhook_events for all to authenticated using(exists(select 1 from public.businesses b where b.id=wallet_webhook_events.business_id and b.owner_id=(select auth.uid()))) with check(exists(select 1 from public.businesses b where b.id=wallet_webhook_events.business_id and b.owner_id=(select auth.uid())));